export type QuotaMetersConfig = {
  key: string;
  enabled?: boolean;
  metadata?: Record<string, unknown>;
};

export function createQuotaMetersConfig(config: QuotaMetersConfig) {
  return {
    key: config.key,
    enabled: config.enabled ?? true,
    metadata: config.metadata ?? {},
  };
}

export const quotaMetersChecks = [
  "Read quota values from the tenant-scoped usage service",
  "Never trust client-submitted usage for enforcement",
  "Keep meter labels synchronized with entitlement definitions",
] as const;

export type QuotaMeterItem = {
  id: string;
  label: string;
  used: number;
  limit: number;
  unit?: string;
};

function formatValue(value: number, unit?: string) {
  return unit ? `${value.toLocaleString()} ${unit}` : value.toLocaleString();
}

export function StackFoundryQuotaMeters({ items }: { items: QuotaMeterItem[] }) {
  return (
    <section className="rounded-lg border p-5">
      <h2 className="font-semibold">Usage</h2>
      <dl className="mt-4 space-y-4">
        {items.map((item) => {
          const percentage = item.limit > 0 ? Math.min(100, Math.round((item.used / item.limit) * 100)) : 0;
          const tone =
            percentage >= 90 ? "bg-destructive" : percentage >= 75 ? "bg-warning" : "bg-primary";

          return (
            <div key={item.id}>
              <div className="flex items-center justify-between text-sm">
                <dt>{item.label}</dt>
                <dd className="text-muted-foreground">
                  {formatValue(item.used, item.unit)} / {formatValue(item.limit, item.unit)}
                </dd>
              </div>
              <div
                className="mt-2 h-2 overflow-hidden rounded-full bg-muted"
                role="progressbar"
                aria-valuemin={0}
                aria-valuemax={item.limit}
                aria-valuenow={item.used}
                aria-label={`${item.label} usage`}
              >
                <div className={`h-full ${tone}`} style={{ width: `${percentage}%` }} />
              </div>
            </div>
          );
        })}
      </dl>
    </section>
  );
}

import { StackFoundryQuotaMeters } from "@/components/stackfoundry/quota-meters";

const items = [
  { id: "requests", label: "API requests", used: 842_500, limit: 1_000_000, unit: "requests" },
  { id: "seats", label: "Team seats", used: 18, limit: 25 },
  { id: "storage", label: "File storage", used: 64, limit: 100, unit: "GB" },
];

export default function QuotaMetersDemo() {
  return <StackFoundryQuotaMeters items={items} />;
}
